// final class ListNode { var val: Int; var next: ListNode?; init(_ v: Int, _ n: ListNode? = nil) { val = v; next = n } }
func mergeKLists(_ lists: [ListNode?]) -> ListNode? {
    var lists = lists
    guard !lists.isEmpty else { return nil }
    while lists.count > 1 {
        var merged: [ListNode?] = []
        for i in stride(from: 0, to: lists.count, by: 2) {
            merged.append(mergeTwoLists(lists[i], i + 1 < lists.count ? lists[i + 1] : nil))
        }
        lists = merged
    }
    return lists[0]
}
